//! Where this build expects to be installed. Generated by `build.rs` from
//! `VINOAUTHFACE_PREFIX` (default `/usr/local`, what deploy.sh installs to; a
//! deb or rpm builds with `/usr`). Fixed at compile time on purpose: the
//! set-group-ID PAM binary and polkit's `exec.path` pins must not depend on
//! an environment a caller controls.

include!(concat!(env!("OUT_DIR"), "/paths.rs"));
